from abc import ABC, abstractmethod

class Robot(ABC):
    @abstractmethod
    def move(self, dst: str) -> str: ...

class VendorAAgv(Robot):
    def move(self, dst):
        return f"A사 AGV: POST /orders {{target:{dst}}}"

class VendorBSorter(Robot):
    def move(self, dst):
        return f"B사 분류기: chute={dst.split('-')[-1]}"

def dispatch(robots, plan):
    for rid, dst in plan:
        print(rid, "→", robots[rid].move(dst))

dispatch({"r1": VendorAAgv(), "s1": VendorBSorter()},
         [("r1", "PICK-07"), ("s1", "CHUTE-12")])
# r1 → A사 AGV: POST /orders {target:PICK-07}
# s1 → B사 분류기: chute=12
